import { BadRequestException, createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IDEMPOTENCY_HEADER = 'idempotency-key';
const VALID_KEY = /^[A-Za-z0-9_\-:.]{8,255}$/;

// Required Idempotency-Key header (e.g. a UUID generated by the POS per checkout)
export const IdempotencyKey = createParamDecorator((_: unknown, ctx: ExecutionContext): string => {
  const value = ctx.switchToHttp().getRequest().header(IDEMPOTENCY_HEADER);
  if (!value) {
    throw new BadRequestException('Idempotency-Key header is required');
  }
  if (!VALID_KEY.test(value)) {
    throw new BadRequestException('Idempotency-Key must be 8-255 chars of letters, digits, "-", "_", ":" or "."');
  }
  return value;
});
